/// The rail entries, in Fleet's order. Only Sessions is rebuilt; the others show a notice.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Rail {
    Sessions,
    Workflows,
    Automations,
    Analytics,
    GitHub,
    Settings,
}

pub struct State {
    /// `None` follows the system's appearance, as Fleet's default "System" theme does.
    pub dark: Option<bool>,
    pub rail: Rail,
    pub sidebar_open: bool,
    pub sidebar_w: f32,
    pub content_open: bool,
    /// The workspace sheet's measured width; 0 until its first layout.
    pub sheet_w: f32,
    /// The theme the last frame was drawn in, so the theme key can flip what is on screen even
    /// while `dark` still follows the system.
    pub drawn_dark: std::cell::Cell<bool>,
    pub projects: Vec<Project>,
    /// The open session: (project, session).
    pub open: (usize, usize),
    pub filter: TextEdit,
    pub draft: TextEdit,
    /// Every session's draft (the open one's text is `draft`; it is put here when another session opens) and the
    /// message history, kept in a file in the app's data folder (`composer::drafts`).
    pub drafts: composer::drafts::Drafts,
    /// Whose text `draft` holds (`draft_owner`).
    draft_of: Option<String>,
    /// Seconds since start, from `poll`.
    pub clock: f64,
    /// When the open session's turn started, on `clock`.
    pub working_since: f64,
    /// A canned reply on its way: (project, session, due).
    reply: Option<(usize, usize, f64)>,
    /// The scripted reply streaming into the long conversation, and when the next one may start.
    script: Option<script::Script>,
    script_next: f64,
    cache: Option<ImageCache>,
    pub logo: Option<Image>,
    /// The Fleet server this window shows, once the connection has started; `None` draws `mock.rs`.
    pub link: Option<Link>,
    pub connection: Connection,
    /// The open session's conversation as the reducer holds it.
    pub stream: Option<StreamState>,
    /// Components that read events the stream doesn't apply (`fleet::state::Subscribers`).
    pub prompts: fleet::prompts::Prompts,
    pub subscribers: fleet::state::Subscribers,
    /// Which session `stream` belongs to, and whether its snapshot is still on the way (what's shown may be a kept copy).
    pub stream_of: Option<String>,
    pub loading: bool,
    /// The conversations of sessions left, shown again at once on return (`keptStreams`).
    pub kept: fleet::topics::Kept,
    /// The "Read N files" groups that are open, by id (`openReads` in `MessageToolList.vue`): closed by default.
    pub open_reads: std::collections::HashSet<String>,
    /// Tool cards the user opened or closed, by part id; a call that fails resets its own (`ToolCard.vue` `isCollapsed`).
    pub tool_open: std::collections::HashMap<String, conv::card::Toggle>,
    /// Tool cards whose output box shows more than the last 12 lines (`expanded` in `ToolOutputBody.vue`).
    pub tool_wide: std::collections::HashSet<String>,
    /// Collapsed context runs the user opened in a diff, and the write cards that show every line (`view::diff`).
    pub diff_open: std::collections::HashSet<String>,
    pub diff_all: std::collections::HashSet<String>,
    /// The "inline tool diffs" setting (`inlineToolDiffs`, off by default): other edit rows show their diff too. Settings
    /// and the palette own the switch; until they are built only a scene turns it on.
    pub inline_diffs: bool,
    /// How thinking is drawn (`weave:thinking`), and the reasoning blocks, compaction summaries and shell commands the user
    /// opened, by part id. Settings owns the choice; until it is built only a scene changes it.
    pub thinking: conv::gist::Thinking,
    pub reasoning_open: std::collections::HashSet<String>,
    pub summary_open: std::collections::HashSet<String>,
    pub shell_wide: std::collections::HashSet<String>,
    /// Finished turns the user opened (`openTurns`), by the turn's first message id, whether you watched the latest turn
    /// run, which session that was about, and what folding left of the messages (`conv::fold_plan`).
    pub turns_open: std::collections::HashSet<String>,
    pub watched: conv::fold::WatchedTurn,
    watched_of: Option<String>,
    pub fold_plan: conv::fold_plan::FoldPlan,
    /// Failure cards whose Details are open, by message id; and each session's Try now / Don't retry in flight or failed
    /// (`fleet::retry`), with the bucket of the countdown last drawn.
    pub failure_open: std::collections::HashSet<String>,
    pub retry_acts: std::collections::HashMap<String, fleet::retry::Act>,
    pub(crate) retry_seen: i64,
    /// The interrupted card's Continue / Dismiss in flight or failed, by session (`fleet::interrupted`).
    pub interrupt_acts: std::collections::HashMap<String, fleet::retry::Act>,
    /// The open session's machine stopped answering: its name (`quietMachine`). The machines list is another
    /// component's, so nothing sets it yet but a scene.
    pub quiet_machine: Option<String>,
    /// What the error box above the composer says (`sendError`, row 1.10): a refused prompt, for now.
    pub composer_error: Option<String>,
    /// A prompt was sent and the session hasn't said it is busy yet (`optimisticBusy`, row 2.11).
    pub optimistic: Option<composer::status::Optimistic>,
    /// The session whose Interrupt is on its way (`aborting`): the button stays off until it is idle.
    pub aborting: Option<String>,
    /// The side conversation is open (component 15 sets it; only a scene does now): rows 1.5 and 2.7.
    pub side_open: bool,
    /// The messages whose command shows its expanded prompt ("Show prompt"), and the one just copied with the second its
    /// "Copied" ends at (`view::message`).
    pub prompt_open: std::collections::HashSet<String>,
    pub copied: Option<(String, f64)>,
    /// The wall clock in unix milliseconds when a scene fixes it; `None` reads the real one (the time pills).
    pub now_ms: Option<i64>,
    /// The agent and model lists, the harness list, the preferences and the effort memory (`fleet::catalog`).
    pub pickers: fleet::catalog::Pickers,
    /// The last thing that went wrong, shown in the status bar.
    pub notice: Option<String>,
    /// The kit's overlays, the palette and the gallery's own controls (`src/ui/`).
    pub ui: ui::Ui,
    /// Shows the kit gallery in place of the sessions view (a scene, `--scene kit`).
    pub gallery: bool,
    /// Stands in for the open session while the list is empty.
    blank: Project,
}

