impl State {
    pub fn project(&self) -> &Project {
        self.projects.get(self.open.0).filter(|p| self.open.1 < p.sessions.len()).unwrap_or(&self.blank)
    }

    pub fn session(&self) -> &Session {
        self.project().sessions.get(self.open.1).unwrap_or(&self.blank.sessions[0])
    }

    /// Every session in list order, for the previous/next keys.
    fn order(&self) -> Vec<(usize, usize)> {
        self.projects.iter().enumerate().flat_map(|(p, project)| (0..project.sessions.len()).map(move |s| (p, s))).collect()
    }

    /// Whether a real or mock session is open (not the blank stand-in).
    pub fn has_session(&self) -> bool {
        self.projects.get(self.open.0).is_some_and(|p| self.open.1 < p.sessions.len())
    }

    pub fn step_session(&mut self, by: isize, tx: &mut Tx) {
        self.step(by, tx);
    }

    /// Shows Fleet's toast for `seconds`, with an optional pill action.
    pub fn toast(&mut self, message: String, action: Option<String>, seconds: f64, tx: &mut Tx) {
        self.ui.toast = Some(ui::toast::Toast { message, action, until: self.clock + seconds, total: seconds });
        tx.wake_after(std::time::Duration::from_millis(100));
    }

    fn step(&mut self, by: isize, tx: &mut Tx) {
        let order = self.order();
        if order.is_empty() {
            return;
        }
        let at = order.iter().position(|&id| id == self.open).unwrap_or(0) as isize;
        let (p, i) = order[(at + by).rem_euclid(order.len() as isize) as usize];
        self.open_session(p, i, tx);
    }
}

impl State {
    /// The session the composer's text belongs to: the open session's id, or a stand-in for the mock data's
    /// sessions, which have none. `None` while a server's list hasn't arrived, so text typed then waits for it.
    pub(crate) fn draft_owner(&self) -> Option<String> {
        match self.open_id() {
            Some(id) => Some(id),
            None if self.link.is_none() => Some(format!("mock.{}.{}", self.open.0, self.open.1)),
            None => None,
        }
    }

    /// What the composer sees of the open session (`composerStatus`): busy while a turn runs or right after a send.
    pub fn composer_status(&self) -> composer::status::ComposerStatus {
        use composer::status::{ComposerStatus, composer_status};
        let activity = match self.session().status {
            Status::Working => "busy",
            Status::NeedsInput => "waiting_input",
            Status::Idle => "idle",
        };
        let status = composer_status(Some(activity), self.optimistic.is_some());
        // A question or permission the session waits on is not a turn the optimistic guess can hide.
        if activity == "waiting_input" { ComposerStatus::WaitingInput } else { status }
    }

    /// Whether the composer takes input at all (`isDisabled`, row 1.9). A session list row without `capabilities` is
    /// taken as able: its `lifecycleStatus` isn't on the row yet, and "running" is what the rule would ask of it.
    pub fn composer_disabled(&self) -> bool {
        let row = &self.session().row;
        let gate = composer::status::SessionGate { archived: row.archived, can_prompt: row.can_prompt, lifecycle: "running" };
        !composer::status::can_send(Some(gate))
    }

    /// Interrupt is live (row 2.4): while a turn runs or the session waits, and no abort is on its way.
    pub fn can_interrupt(&self) -> bool {
        let aborting = self.aborting.is_some() && self.aborting == self.draft_owner();
        !self.composer_disabled() && composer::status::can_interrupt(self.composer_status(), aborting)
    }

    /// Report this: the problem-report dialog is not in the native app yet (component 17 of the port).
    pub fn report_turn_failure(&mut self, _summary: &str, tx: &mut Tx) {
        self.toast("The problem report isn't in the native app yet.".into(), None, 4.0, tx);
    }

    /// A scene: the open session's composer holds `text` (put in the drafts, which the first frame reads back).
    pub fn show_draft(&mut self, text: &str) {
        if let Some(owner) = self.draft_owner() {
            self.drafts.write(&composer::drafts::session_draft_key(&owner), text, 0.0);
        }
    }

    /// Scenes for the composer's states (docs/parity/05-composer.md, piece B).
    pub fn show_composer(&mut self, state: &str) {
        match state {
            "idle" => self.open = (0, 2),
            "typed" => {
                self.open = (0, 2);
                self.show_draft("Add a test for the rename step too.");
            }
            "busy" => {
                self.open = (0, 0);
                self.show_draft("Also keep the 200 MB limit.");
            }
            "disabled" => {
                self.open = (0, 2);
                self.projects[0].sessions[2].row.archived = true;
            }
            "error" => {
                self.open = (0, 2);
                self.show_draft("Run the cache tests again.");
                self.composer_error = Some("HTTP 500".into());
            }
            "long" => {
                self.open = (0, 2);
                let lines: Vec<String> = (1..=12).map(|n| format!("Step {n}: read the file and say what it does.")).collect();
                self.show_draft(&lines.join("\n"));
            }
            "side" => {
                self.open = (0, 2);
                self.side_open = true;
            }
            // The effort toggle (a model with levels, the third picked) and the pickers' menus.
            "effort" => {
                self.open = (0, 2);
                let owner = self.draft_owner().unwrap_or_default();
                let model = composer::choice::create_model_selection_key("anthropic", "opus-5-5");
                self.drafts.set_choice(&owner, composer::drafts::Choice { model, effort: "high".into(), ..Default::default() });
            }
            "agent-menu" => {
                self.open = (0, 2);
                self.open_selector("agent");
            }
            "model-menu" => {
                self.open = (0, 2);
                self.open_selector("model");
            }
            // Typed text keeps the rows that contain it; the highlight moves to the first match.
            "model-filtered" => {
                self.open = (0, 2);
                self.open_selector("model");
                self.ui.sel.filter = rune::TextEdit::new("o");
                self.keep_selector();
            }
            // Nothing matches: Default stays (it always does), so the list never goes empty.
            "model-nomatch" => {
                self.open = (0, 2);
                self.open_selector("model");
                self.ui.sel.filter = rune::TextEdit::new("zzz");
                self.keep_selector();
            }
            // A favourite on top of the list, and the pointer on a row that isn't starred.
            "model-starred" => {
                self.open = (0, 2);
                let key = composer::groups::model_picker_key("opencode", "anthropic", "opus-5-5");
                let picker = composer::groups::ModelPicker { favourites: vec![key], ..Default::default() };
                self.pickers.prefs.set(composer::groups::PREFERENCE_KEY, &picker.to_json());
                self.open_selector("model");
                self.ui.sel.active = 3;
            }
            "models-long" => {
                self.open = (0, 2);
                self.pickers.add_mock_models(15);
                self.open_selector("model");
            }
            _ => {}
        }
    }

    /// The drafts file was read: its text joins what is in memory, and the text area shows its session's if empty.
    pub fn adopt_drafts(&mut self, dir: std::path::PathBuf, stored: composer::drafts::Stored) {
        self.drafts.set_dir(Some(dir));
        self.drafts.merge(stored);
        if let Some(owner) = self.draft_of.clone()
            && self.draft.text.is_empty()
        {
            self.draft = TextEdit::new(self.drafts.text_of(&owner));
        }
    }

    /// Keeps a draft per session (`docs/parity/05-composer.md`, piece A; Fleet's `useDraftState`): when another
    /// session is open the text area's text is put away under the one it was and the new one's comes back; what
    /// is typed is noted, and written to the file a moment after the last change, on a thread.
    fn keep_drafts(&mut self, now: f64, tx: &mut Tx) {
        let Some(owner) = self.draft_owner() else { return };
        if self.draft_of.as_deref() != Some(owner.as_str()) {
            let had_old = self.draft_of.is_some();
            if let Some(old) = self.draft_of.take() {
                self.drafts.write(&composer::drafts::session_draft_key(&old), &self.draft.text, now);
            }
            self.draft = TextEdit::new(self.drafts.text_of(&owner));
            self.draft_of = Some(owner.clone());
            // The error box, the optimistic busy and an abort on its way belong to the composer of one session
            // (not cleared on the first look, so a scene can set them).
            if had_old {
                self.composer_error = None;
                self.optimistic = None;
                self.aborting = None;
            }
        } else if self.drafts.text_of(&owner) != self.draft.text {
            self.drafts.write(&composer::drafts::session_draft_key(&owner), &self.draft.text, now);
        }
        if self.drafts.save_due(now) {
            if let Some((dir, json)) = self.drafts.take_save() {
                composer::drafts::spawn_save(dir, json);
            }
        } else if self.drafts.unsaved() {
            tx.wake_after(std::time::Duration::from_secs_f64(composer::drafts::SAVE_AFTER));
        }
    }
}

/// Enter, Ctrl/Cmd+Enter and the Send button (`handleSend`, row 2.10): the draft goes where `route_draft` says.
/// `modifier` is the other choice of Enter: steer where Enter queues, queue where it steers. Only prompts have a
/// route yet; what the other routes need is built in pieces I (queue, steer), K and M (commands, shell, `/btw`),
/// so a command or a `!` draft still goes as the text it is, as before.
pub fn submit(s: &mut State, tx: &mut Tx, modifier: bool) {
    if s.composer_disabled() {
        return;
    }
    let caps = composer::status::Caps::default();
    let cx = composer::route::DraftContext {
        status: s.composer_status(),
        steer: composer::route::steer_for_key(&caps, modifier),
        caps,
        side_open: s.side_open,
    };
    match composer::route::route_draft(&s.draft.text, &cx) {
        composer::route::Route::Empty => {}
        // Component 15 fills this in; the draft stays, as the kit's `waiting()` entries do.
        composer::route::Route::Side { .. } => {
            s.toast("The side conversation isn't in the native app yet (component 15 of the port).".into(), None, 4.0, tx)
        }
        _ => {
            send(s, tx);
            tx.focus("composer", false);
        }
    }
}

/// The composer's Send: the message joins the conversation, and a canned reply follows.
pub fn send(s: &mut State, tx: &mut Tx) {
    let text = s.draft.text.trim().to_string();
    if text.is_empty() {
        return;
    }
    // Row 8.1: what is sent is remembered for ArrowUp, before it goes anywhere.
    if let Some(owner) = s.draft_owner() {
        let now = s.clock;
        s.drafts.push_history(&owner, &text, now);
    }
    send_text(s, tx, text);
    s.draft.clear();
}

/// "Try again" on a failure card: the last prompt goes again, as a new message (`retryPrompt`).
pub fn retry_turn(s: &mut State, tx: &mut Tx) {
    if s.composer_disabled() {
        return;
    }
    if let Some(text) = view::failure::last_prompt(&s.session().messages) {
        send_text(s, tx, text);
    }
}

/// Sends `text` to the open session. On a server the message goes to the agent, and the conversation shows it at once,
/// as sent but not yet confirmed; without one, a canned reply follows.
fn send_text(s: &mut State, tx: &mut Tx, text: String) {
    s.composer_error = None;
    s.optimistic = Some(composer::status::Optimistic::new(s.clock));
    tx.wake_after(std::time::Duration::from_secs_f64(composer::status::Optimistic::GIVE_UP + 0.1));
    if let (Some(_), Some(id)) = (&s.link, s.open_id()) {
        s.send_to_server(&id, &text);
        s.notice = None;
        tx.scroll_to_bottom("stream");
        tx.wake_after(std::time::Duration::from_secs_f64(composer::status::Optimistic::GIVE_UP + 0.1));
        // `poll` turns what is still unconfirmed by then into "retry".
        tx.wake_after(std::time::Duration::from_secs_f64(fleet::prompts::CONFIRMATION_TIMEOUT + 0.1));
        return;
    }
    let (p, i) = s.open;
    let session = &mut s.projects[p].sessions[i];
    let id = format!("u{}", session.messages.len() + 1);
    session.messages.push(Message::user(id, text));
    session.status = Status::Working;
    session.age = "now".into();
    session.dim = 1.0;
    s.working_since = s.clock;
    s.reply = Some((p, i, s.clock + 2.5));
    tx.scroll_to_bottom("stream");
    tx.wake_after(std::time::Duration::from_millis(2600));
}

/// Esc, and the composer's Interrupt button.
pub fn interrupt(s: &mut State) {
    if !s.can_interrupt() {
        return;
    }
    s.aborting = s.draft_owner();
    s.optimistic = None;
    if let (Some(link), Some(id)) = (&s.link, s.open_id()) {
        link.abort(&id);
        return;
    }
    let (p, i) = s.open;
    let session = &mut s.projects[p].sessions[i];
    if session.status != Status::Idle {
        session.status = Status::Idle;
        end_tools(session);
        s.reply = None;
        s.script = None;
        s.script_next = f64::INFINITY;
    }
}

/// A turn that ends takes its running tool calls with it.
fn end_tools(session: &mut Session) {
    for part in session.messages.iter_mut().flat_map(|m| m.parts.iter_mut()) {
        if let Part::Tool { status, .. } = part
            && *status == ToolStatus::Running
        {
            *status = ToolStatus::Completed;
        }
    }
}

fn poll(s: &mut State, now: f64, tx: &mut Tx) -> bool {
    let composer_changed = s.keep_composer_state(now);
    // "Copied" on a message's button ends by itself.
    let copied = match &s.copied {
        Some((_, until)) if now >= *until => {
            s.copied = None;
            true
        }
        Some(_) => {
            tx.wake_after(std::time::Duration::from_millis(100));
            false
        }
        None => false,
    };
    poll_rest(s, now, tx) || composer_changed || copied
}

impl State {
    /// The composer's guesses end with the session's own word: true when one did and the buttons must redraw.
    fn keep_composer_state(&mut self, now: f64) -> bool {
        let busy = self.session().status == Status::Working;
        let mut changed = false;
        if let Some(o) = &mut self.optimistic
            && !o.keep(busy, now)
        {
            self.optimistic = None;
            changed = true;
        }
        if self.aborting.is_some() && self.session().status == Status::Idle {
            self.aborting = None;
            changed = true;
        }
        changed
    }
}

fn poll_rest(s: &mut State, now: f64, tx: &mut Tx) -> bool {
    // Whole seconds only, so the "Working · 18s" label redraws once a second.
    let ticked = now.floor() != s.clock.floor();
    s.clock = now;
    s.keep_drafts(now, tx);
    if s.prompts.expire(now) {
        s.sync_open();
        return true;
    }
    let toast = match &s.ui.toast {
        Some(t) if now >= t.until => {
            s.ui.toast = None;
            true
        }
        Some(_) => {
            tx.wake_after(std::time::Duration::from_millis(100));
            true
        }
        None => false,
    };
    if toast {
        return true;
    }
    match s.reply {
        Some((p, i, due)) if now >= due => {
            let session = &mut s.projects[p].sessions[i];
            end_tools(session);
            let id = format!("a{}", session.messages.len() + 1);
            let reply = Part::text(format!("{id}-t"), mock::CANNED_REPLY);
            session.messages.push(Message::assistant(id, vec![reply]));
            session.status = Status::Idle;
            s.reply = None;
            tx.scroll_to_bottom("stream");
            true
        }
        _ => s.tick_script() || (ticked && s.session().status == Status::Working) || s.keep_retry_clock(tx),
    }
}

fn on_key(s: &mut State, ev: &KeyEvent, tx: &mut Tx) -> bool {
    if ev.is_command('k') {
        ui::palette::toggle(s, tx);
    } else if ev.is_command('b') && ev.mods.shift {
        s.content_open = !s.content_open;
    } else if ev.is_command('b') {
        s.sidebar_open = !s.sidebar_open;
    } else if ev.is_command('[') {
        s.step(-1, tx);
    } else if ev.is_command(']') {
        s.step(1, tx);
    } else if ev.is_command('l') && ev.mods.shift {
        // Not a Fleet shortcut: a quick way to see both themes in the prototype.
        s.dark = Some(!s.drawn_dark.get());
    } else if ev.key == Key::Escape {
        interrupt(s);
    } else {
        return false;
    }
    true
}

fn setup(s: &mut State, waker: rune::Waker) {
    let cache = s.cache.insert(ImageCache::new(waker));
    let logo = cache.load(&include_bytes!("../assets/weave_logo.png")[..]);
    // Decoded before the first frame, so a headless snapshot has the logo in it.
    #[cfg(not(target_arch = "wasm32"))]
    let _ = logo.wait();
    s.logo = Some(logo);
}

